    "id": "o9IErbpmItz9NZT3",
    "name": "Blackaxe",
    "img": "systems/pf2e/icons/equipment/artifacts/blackaxe.webp",
    "slug": "blackaxe",
    "level": 25,
    "base": "greataxe",
