    "id": "IEA7M6GGv4rnGLdW",
    "name": "Bladed Hoop",
    "img": "systems/pf2e/icons/equipment/weapons/bladed-hoop.webp",
    "slug": "bladed-hoop",
    "level": 0,
    "base": "bladed-hoop",
