    "id": "WrNHmsU8ZaBY3V9S",
    "name": "Whispering Staff",
    "img": "icons/weapons/staves/staff-simple-spiral-brown.webp",
    "slug": "whispering-staff",
    "level": 20,
    "base": "staff",
    "group": "club",
